let activity = app('{NodeApiAppInsights:name}').customEvents
    | where name == "CAMS Sign-In"
    | project timestamp, who = tostring(customDimensions.email);
let RangeStart = {TimeRange:start};
let RangeEnd = {TimeRange:end};
let Missing = toscalar(activity | where timestamp >= RangeStart and timestamp < RangeEnd | where isempty(who) | count);
let ActiveNote = case(
    Missing == 1, "1 sign-in had no work email and is not counted",
    Missing > 1, strcat(Missing, " sign-ins had no work email and are not counted"),
    "");
let RangeDuration = RangeEnd - RangeStart;
let PriorStart = RangeStart - RangeDuration;
let CountedFrom = toscalar(activity | summarize min(timestamp));
let ids = activity | where isnotempty(who);
let Active = toscalar(ids | where timestamp >= RangeStart and timestamp < RangeEnd | distinct who | count);
let Prior = toscalar(ids | where timestamp >= PriorStart and timestamp < RangeStart | distinct who | count);
let New = toscalar(
    ids
    | summarize firstSeen = min(timestamp) by who
    | where firstSeen >= RangeStart and firstSeen < RangeEnd
    | count
);
let PriorCovered = isnotnull(CountedFrom) and PriorStart >= CountedFrom;
let NewOverstated = isnotnull(CountedFrom) and RangeStart < CountedFrom + 30d;
let GrowthPercent = iff(PriorCovered and Prior > 0, round(100.0 * (Active - Prior) / Prior, 1), real(null));
union
    (print Order = 1, Metric = "Active People (selected period)", Value = toreal(Active), Note = ActiveNote),
    (print Order = 2, Metric = "New People (selected period)", Value = toreal(New),
        Note = iff(NewOverstated, strcat("Overstated: anyone active before ", format_datetime(CountedFrom, "yyyy-MM-dd"), " counts as new"), "")),
    (print Order = 3, Metric = "Growth % (vs. prior period)", Value = GrowthPercent,
        Note = case(
            not(PriorCovered), "Not available: the prior period starts before people were counted",
            Prior == 0, "Not available: no one was active in the prior period",
            ""))
| order by Order asc
| project Metric, Value, Note

let activity = app('{NodeApiAppInsights:name}').customEvents
    | where name == "CAMS Sign-In"
    | project timestamp, who = tostring(customDimensions.email);
let RangeStart = {TimeRange:start};
let RangeEnd = {TimeRange:end};
let FirstDay = startofday(RangeStart);
let LastDay = startofday(RangeEnd - 1tick);
let CountedFromDay = startofday(toscalar(activity | summarize min(timestamp)));
let activeDays = activity
    | where isnotempty(who)
    | where timestamp >= FirstDay - 29d and timestamp < RangeEnd
    | distinct Day = startofday(timestamp), who;
let dau = activeDays
    | summarize DAU = count() by Day;
let wau = activeDays
    | mv-expand WindowDay = range(Day, Day + 6d, 1d) to typeof(datetime)
    | distinct WindowDay, who
    | summarize WAU = count() by Day = WindowDay;
let mau = activeDays
    | mv-expand WindowDay = range(Day, Day + 29d, 1d) to typeof(datetime)
    | distinct WindowDay, who
    | summarize MAU = count() by Day = WindowDay;
range Day from FirstDay to LastDay step 1d
| where isnotnull(CountedFromDay) and Day >= CountedFromDay
| join kind=leftouter dau on Day
| join kind=leftouter wau on Day
| join kind=leftouter mau on Day
| project Day, DAU = coalesce(DAU, 0), WAU = coalesce(WAU, 0), MAU = coalesce(MAU, 0)
| extend Stickiness = round(iff(MAU > 0, 100.0 * DAU / MAU, 0.0), 1)
| order by Day asc

let activity = app('{NodeApiAppInsights:name}').customEvents
    | where name == "CAMS Sign-In"
    | project timestamp, who = tostring(customDimensions.email);
let RangeStart = {TimeRange:start};
let RangeEnd = {TimeRange:end};
let ids = activity | where isnotempty(who);
let firstSeen = ids | summarize FirstSeen = min(timestamp) by who;
ids
| where timestamp >= RangeStart and timestamp < RangeEnd
| distinct who
| join kind=inner firstSeen on who
| extend Status = iff(FirstSeen >= RangeStart, "New", "Returning")
| summarize People = count() by Status
| order by Status asc

